-- AgroDosis · datos iniciales (portafolio Ecuaquímica para pitahaya + plan sanitario)
-- Ejecutar UNA sola vez, después de schema.sql.
begin;


select setval(pg_get_serial_sequence('etapas', 'id'), (select max(id) from etapas));

select setval(pg_get_serial_sequence('productos', 'id'), (select max(id) from productos));

select setval(pg_get_serial_sequence('problemas', 'id'), (select max(id) from problemas));

select setval(pg_get_serial_sequence('recomendaciones', 'id'), (select max(id) from recomendaciones));

select setval(pg_get_serial_sequence('plan_sanitario', 'id'), (select max(id) from plan_sanitario));

select setval(pg_get_serial_sequence('plan_fertilizacion', 'id'), (select max(id) from plan_fertilizacion));

select setval(pg_get_serial_sequence('compatibilidad', 'id'), (select max(id) from compatibilidad));


select publicar_catalogo();
commit;
